// Nilad F1 — verify WooCommerce webhook HMAC + validate + normalize + duplicate check.
// Requires: NODE_FUNCTION_ALLOW_BUILTIN=crypto, env WOO_WEBHOOK_SECRET,
// Webhook node option Raw Body ON (raw bytes at binary.data.data, base64).
// Outputs: { ok, reason, duplicate, orderId, total, city, phone, phoneValid,
//            status, createdAt, paymentMethod, customerName, itemsText }
const crypto = require('crypto');
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const secret = $env.WOO_WEBHOOK_SECRET;

let ok = false;
let reason = '';
const rawB64 = item.binary && item.binary.data && item.binary.data.data;
const sig = headers['x-wc-webhook-signature'] || headers['X-WC-Webhook-Signature'] || '';

if (!secret) {
  reason = 'server-misconfig: WOO_WEBHOOK_SECRET missing';
} else if (!rawB64) {
  reason = 'no-raw-body: enable Raw Body on the Webhook node';
} else if (!sig) {
  reason = 'missing-signature-header';
} else {
  const expected = crypto.createHmac('sha256', secret).update(Buffer.from(rawB64, 'base64')).digest('base64');
  const a = Buffer.from(String(sig));
  const b = Buffer.from(expected);
  ok = a.length === b.length && crypto.timingSafeEqual(a, b);
  reason = ok ? 'valid' : 'bad-signature';
}

const body = (item.json && item.json.body) || {};
const orderId = typeof body.id === 'number' ? body.id : null;
if (ok && orderId === null) {
  ok = false;
  reason = 'missing-order-id';
}

function normalizePhone(raw) {
  const trimmed = String(raw || '').trim();
  if (!trimmed) return { phone: '', phoneValid: false };
  const cleaned = trimmed.replace(/[^\d+]/g, '');
  let p = cleaned;
  if (p.startsWith('0020')) p = '+20' + p.slice(4);
  else if (p.startsWith('+20')) { /* already */ }
  else if (p.startsWith('0')) p = '+20' + p.slice(1);
  const phoneValid = /^\+20(10|11|12|15)\d{8}$/.test(p);
  return { phone: phoneValid ? p : trimmed, phoneValid };
}

const rawPhone = (body.billing && body.billing.phone) || (body.shipping && body.shipping.phone) || '';
const { phone, phoneValid } = normalizePhone(rawPhone);
const lines = Array.isArray(body.line_items) ? body.line_items : [];
const itemsText = lines.map((l) => `${l.name || 'منتج'} ×${l.quantity || 1}`).join('\n');
const billing = body.billing || {};
const shipping = body.shipping || {};
const total = Number.isFinite(parseFloat(body.total)) ? parseFloat(body.total) : 0;
const customerName = `${billing.first_name || ''} ${billing.last_name || ''}`.trim() || shipping.first_name || '';

const sd = $getWorkflowStaticData('global');
sd.processed = Array.isArray(sd.processed) ? sd.processed : [];
const duplicate = ok && sd.processed.includes('f1:' + orderId);

return [{
  json: {
    ok,
    reason,
    duplicate,
    orderId,
    total,
    city: shipping.city || billing.city || '',
    phone,
    phoneValid,
    status: body.status || '',
    createdAt: body.date_created || '',
    paymentMethod: body.payment_method_title || body.payment_method || '',
    customerName,
    itemsText
  }
}];

// Nilad F1 — mark order processed (idempotency write). Passthrough output.
const sd = $getWorkflowStaticData('global');
sd.processed = Array.isArray(sd.processed) ? sd.processed : [];
const key = 'f1:' + $input.first().json.orderId;
if (!sd.processed.includes(key)) sd.processed.push(key);
if (sd.processed.length > 500) sd.processed.splice(0, sd.processed.length - 500);
return [{ json: { ...$input.first().json } }];

// Nilad F1 — build the owner Telegram text (Arabic, HTML-escaped) + Sheet row.
// Outputs ONLY: { orderId, total, city, phone, status, createdAt, tgText }
// (sheet headers = orderId,total,city,phone,status,createdAt — extra tgText ignored by autoMap)
const j = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = String(j.itemsText || '').split('\n').map((l) => '  • ' + esc(l)).join('\n');
const phoneLine = j.phone ? `${esc(j.phone)} ${j.phoneValid ? '✅' : '⚠️'}` : 'بدون رقم';
const tgText = [
  '🛍 <b>طلب جديد #' + esc(j.orderId) + '</b>',
  '👤 ' + esc(j.customerName || 'زبون'),
  '📱 ' + phoneLine,
  '📦\n' + lines,
  '💰 <b>' + esc(j.total) + ' ج.م</b> — ' + esc(j.city || '—'),
  '🧾 ' + esc(j.status) + ' · ' + esc(j.paymentMethod || '')
].join('\n');
return [{
  json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '',
    orderId: j.orderId,
    total: j.total,
    city: j.city,
    phone: j.phone,
    status: j.status,
    createdAt: j.createdAt,
    tgText
  }
}];
